package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.persistence.*; import com.wiseway.web.NotFoundException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class SavedRouteService { private final SavedRouteRepository repo; public SavedRouteService(SavedRouteRepository r){repo=r;} public List<RouteResponse> list(){return repo.findAll().stream().map(this::out).toList();} public RouteResponse get(Long id){return out(repo.findById(id).orElseThrow(()->new NotFoundException("Saved route not found.")));} @Transactional public RouteResponse create(RouteRequest r){return out(repo.save(new SavedRouteEntity(r.label().trim(),r.origin().trim(),r.destination().trim(),r.preferredMode(),r.preferenceProfile())));} @Transactional public RouteResponse update(Long id,RouteRequest r){var e=repo.findById(id).orElseThrow(()->new NotFoundException("Saved route not found."));e.update(r.label().trim(),r.origin().trim(),r.destination().trim(),r.preferredMode(),r.preferenceProfile());return out(e);} @Transactional public void delete(Long id){if(!repo.existsById(id))throw new NotFoundException("Saved route not found.");repo.deleteById(id);} private RouteResponse out(SavedRouteEntity e){return new RouteResponse(e.getId(),e.getLabel(),e.getOrigin(),e.getDestination(),e.getPreferredMode(),e.getPreferenceProfile(),e.getCreatedAt(),e.getUpdatedAt());}}
